INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (370024, 15787, 'The Times of India', 'en', '‘No safe harbour if law violated’: Govt’s message to Meta on content moderation', 'https://timesofindia.indiatimes.com/india/no-safe-harbour-if-law-violated-governments-message-to-meta-on-content-moderation/articleshow/133313710.cms', 'India has warned Meta that safe-harbour protection is not guaranteed if laws are violated. Discussions focused on content moderation and child sexual abuse material handling. The government seeks greater local sensitivity in content moderation decisions. Deepfakes and synthetically generated content require clear labeling for users. WhatsApp usernames are also being examined across all messaging platforms.', 'https://static.toiimg.com/photo/msid-133313884,imgsize-99872.cms', '2026-08-18T06:51:16+00:00', '2026-08-18T07:26:42.765423'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
