INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (370359, 15787, 'The Hindu BusinessLine', 'en', 'Centre tells Meta safe harbour won''t cover CSAM violations: Govt Sources', 'https://www.thehindubusinessline.com/info-tech/centre-tells-meta-safe-harbour-wont-cover-csam-violations-govt-sources/article71359287.ece', 'The government tells Meta that its content moderation mechanisms need to demonstrate greater sensitivity to India''s linguistic and cultural context rather than relying solely on global standards', 'https://bl-i.thgim.com/public/incoming/yqoxa1/article71355348.ece/alternates/LANDSCAPE_1200/2024-03-06T165009Z_417791169_RC27C3ANIJ4Y_RTRMADP_3_META-PLATFORMS-STATES.JPG', '2026-08-18T07:21:57+00:00', '2026-08-18T07:29:56.998632'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
