INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (371298, 15787, 'The Economic Times', 'en', 'Govt presses Meta on WhatsApp username row', 'https://economictimes.indiatimes.com/news/india/message-has-gone-home-govt-presses-meta-on-csam-whatsapp-username-row/articleshow/133315982.cms', 'New Delhi: The government''s hard talk with Meta has led to action and increased sensitivity on the issue of child sexual abuse material (CSAM), IT Ministry sources said on Tuesday, adding that the Centre has been unequivocal that such content is a clear violation and there is no safe harbour when law is violated in this manner.Sources said the government''s intent is not about censorship or restricting coverage in any way, but ensuring Indian laws and norms are followed and that social media harms are mitigated. "The message has gone home," they said.Also read: Meta, YouTube, TikTok face thousa', '', '2026-08-18T08:05:58+00:00', '2026-08-18T08:20:53.163584'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
